--Update for voided ticket bettrans
UPDATE tv SET tv.IssueTypeID = 11, tv.SubIssueTypeID = 27
FROM dbo.TicketVoiding_VoidedTransaction tv WITH (ROWLOCK, UPDLOCK)
INNER JOIN #TransIds_bettrans b ON b.TransId = tv.TransId

--Insert into TicketVoiding_VoidedTransaction for bettrans14
DECLARE @ReasonId INT = 0 
INSERT INTO dbo.TicketVoiding_Reason (ReasonEnglish, ReasonChineseSimplified)
SELECT 'Abnormal bet',N'由于非正常投注'
	
SET @ReasonId = SCOPE_IDENTITY()
	
